(509, 1, '2025-07-02 10:19:15', '2025-07-02 10:19:15', '<ul data-start=\"493\" data-end=\"983\">\r\n 	<li data-start=\"493\" data-end=\"532\">\r\n<p data-start=\"495\" data-end=\"532\">Display: 6.1\" Super Retina XDR OLED</p>\r\n</li>\r\n 	<li data-start=\"533\" data-end=\"563\">\r\n<p data-start=\"535\" data-end=\"563\">Processor: A16 Bionic Chip</p>\r\n</li>\r\n 	<li data-start=\"564\" data-end=\"576\">\r\n<p data-start=\"566\" data-end=\"576\">RAM: 6GB</p>\r\n</li>\r\n 	<li data-start=\"577\" data-end=\"612\">\r\n<p data-start=\"579\" data-end=\"612\">Storage: 128GB (Non-expandable)</p>\r\n</li>\r\n 	<li data-start=\"613\" data-end=\"661\">\r\n<p data-start=\"615\" data-end=\"661\">Rear Camera: 48MP (Main) + 12MP (Ultra-wide)</p>\r\n</li>\r\n 	<li data-start=\"662\" data-end=\"694\">\r\n<p data-start=\"664\" data-end=\"694\">Front Camera: 12MP TrueDepth</p>\r\n</li>\r\n 	<li data-start=\"695\" data-end=\"737\">\r\n<p data-start=\"697\" data-end=\"737\">Battery: Up to 20 hours video playback</p>\r\n</li>\r\n 	<li data-start=\"738\" data-end=\"793\">\r\n<p data-start=\"740\" data-end=\"793\">Charging: Fast Charging + MagSafe Wireless Charging</p>\r\n</li>\r\n 	<li data-start=\"794\" data-end=\"808\">\r\n<p data-start=\"796\" data-end=\"808\">OS: iOS 17</p>\r\n</li>\r\n 	<li data-start=\"809\" data-end=\"820\">\r\n<p data-start=\"811\" data-end=\"820\">Face ID</p>\r\n</li>\r\n 	<li data-start=\"821\" data-end=\"835\">\r\n<p data-start=\"823\" data-end=\"835\">5G Support</p>\r\n</li>\r\n 	<li data-start=\"836\" data-end=\"893\">\r\n<p data-start=\"838\" data-end=\"893\">Dual eSIM or eSIM + Physical SIM (Depending on model)</p>\r\n</li>\r\n 	<li data-start=\"894\" data-end=\"941\">\r\n<p data-start=\"896\" data-end=\"941\">Color: Black / Blue / Pink / Green / Yellow</p>\r\n</li>\r\n 	<li data-start=\"942\" data-end=\"983\">\r\n<p data-start=\"944\" data-end=\"983\">Body: Aluminum and Ceramic Shield front</p>\r\n</li>\r\n</ul>', 'iPhone 15', '<p data-start=\"246\" data-end=\"402\">iPhone 15 delivers powerful performance with A16 Bionic chip, an advanced 48MP main camera, and sleek design — perfect for users seeking premium experience.</p>\r\n\r\n<blockquote data-start=\"404\" data-end=\"456\">\r\n<p data-start=\"406\" data-end=\"456\"></p>\r\n</blockquote>', 'publish', 'open', 'closed', '', 'iphone-15', '', '', '2025-07-06 15:50:17', '2025-07-06 15:50:17', '', 0, 'http://localhost/final%20project_3/?post_type=product&#038;p=509', 0, 'product', '', 0),
