(842, 1, '2025-07-03 16:22:53', '2025-07-03 16:22:53', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Smartify Footer</title>\n  <style>\n    body {\n      margin: 0;\n      padding: 0;\n      font-family: Arial, sans-serif;\n    }\n    .site-footer {\n      background-color: #000;\n      color: #fff;\n      padding: 40px 0 20px;\n    }\n    .footer-container {\n      display: flex;\n      flex-wrap: wrap;\n      justify-content: space-around;\n      max-width: 1200px;\n      margin: auto;\n      padding: 0 20px;\n    }\n    .footer-column {\n      flex: 1 1 250px;\n      margin: 20px;\n    }\n    .footer-column h3,\n    .footer-column h4 {\n      margin-bottom: 15px;\n      font-weight: bold;\n      color: #ffffff;\n    }\n    .footer-column p,\n    .footer-column li {\n      font-size: 14px;\n      color: #ccc;\n    }\n    .footer-column ul {\n      list-style: none;\n      padding: 0;\n    }\n    .footer-column ul li {\n      margin-bottom: 8px;\n    }\n    .footer-column ul li a {\n      color: #ccc;\n      text-decoration: none;\n      transition: color 0.3s;\n    }\n    .footer-column ul li a:hover {\n      color: #ffffff;\n    }\n    .footer-bottom {\n      text-align: center;\n      border-top: 1px solid #333;\n      margin-top: 30px;\n      padding-top: 15px;\n      font-size: 13px;\n      color: #999;\n    }\n    @media (max-width: 768px) {\n      .footer-container {\n        flex-direction: column;\n        text-align: center;\n      }\n    }\n  </style>\n</head>\n<body>\n  <!-- ======= Smartify Footer ======= -->\n  <footer>\n        <h3>Smartify</h3>\n        <p>Empowering your digital lifestyle with top-notch electronics.</p>\n        <h4>Quick Links</h4>\n       <ul>\n  <li><a href=\"http://localhost/final%20project_3/\">Home</a></li> \n  <li><a href=\"http://localhost/final%20project_3/?post_type=product\">Shop</a></li> \n  <li><a href=\"http://localhost/final%20project_3/?page_id=542\">About</a></li> \n  <li><a href=\"http://localhost/final%20project_3/?page_id=578\">Customer Testimonials</a></li> \n  <li><a href=\"http://localhost/final%20project_3/?page_id=546\">FAQ</a></li> \n  <li><a href=\"http://localhost/final%20project_3/?page_id=391\">Blog</a></li> \n  <li><a href=\"http://localhost/final%20project_3/?page_id=393\">Contact Us</a></li>\n</ul>\n        <h4>Get in Touch</h4>\n        <p>Email: support@smartify.com</p>\n        <p>Phone: +20 123 456 789</p>\n      <p>&copy; 2025 Smartify. All rights reserved.</p>\n  </footer>\n</body>\n</html>', 'footer_en', '', 'inherit', 'closed', 'closed', '', '824-revision-v1', '', '', '2025-07-03 16:22:53', '2025-07-03 16:22:53', '', 824, 'http://localhost/final%20project_3/?p=842', 0, 'revision', '', 0),
