INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(845, 1, '2025-07-03 16:27:25', '2025-07-03 16:27:25', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <title>Smartify Footer</title>\n  <style>\n    /* Reset */\n    * {\n      margin: 0;\n      padding: 0;\n      box-sizing: border-box;\n    }\n    body {\n      font-family: Arial, sans-serif;\n    }\n    /* Footer Styles */\n    .site-footer {\n      background-color: #000;\n      color: #fff;\n      padding: 40px 20px 20px;\n      width: 100%;\n    }\n    .footer-container {\n      max-width: 1200px;\n      margin: 0 auto;\n      display: flex;\n      flex-wrap: wrap;\n      justify-content: space-between;\n      gap: 30px;\n    }\n    .footer-column {\n      flex: 1 1 250px;\n    }\n    .footer-column h3,\n    .footer-column h4 {\n      margin-bottom: 15px;\n      font-weight: bold;\n    }\n    .footer-column p {\n      font-size: 14px;\n      line-height: 1.6;\n    }\n    .footer-links {\n      list-style: none;\n      padding: 0;\n      margin: 0;\n    }\n    .footer-links li {\n      margin-bottom: 8px;\n    }\n    .footer-links a {\n      color: #fff;\n      text-decoration: none;\n      transition: color 0.3s ease;\n    }\n    .footer-links a:hover {\n      color: #ddd;\n    }\n    .footer-bottom {\n      border-top: 1px solid #333;\n      margin-top: 30px;\n      padding-top: 20px;\n      text-align: center;\n      font-size: 14px;\n    }\n  </style>\n</head>\n<body>\n  <!-- Footer Start -->\n  <footer>\n        <h3>Smartify</h3>\n        <p>Your trusted tech store for laptops, smartwatches, accessories, and more.</p>\n        <h4>Quick Links</h4>\n        <ul>\n          <li><a href=\"http://localhost/final%20project_3/\">Home</a></li>\n          <li><a href=\"http://localhost/final%20project_3/?post_type=product\">Shop</a></li>\n          <li><a href=\"http://localhost/final%20project_3/?page_id=542\">About</a></li>\n          <li><a href=\"http://localhost/final%20project_3/?page_id=578\">Customer Testimonials</a></li>\n          <li><a href=\"http://localhost/final%20project_3/?page_id=546\">FAQ</a></li>\n          <li><a href=\"http://localhost/final%20project_3/?page_id=391\">Blog</a></li>\n          <li><a href=\"http://localhost/final%20project_3/?page_id=393\">Contact Us</a></li>\n        </ul>\n        <h4>Contact</h4>\n        <p>Email: support@smartify.com</p>\n        <p>Phone: +20 123 456 7890</p>\n      <p>© 2025 Smartify. All rights reserved.</p>\n  </footer>\n  <!-- Footer End -->\n</body>\n</html>', 'footer_en', '', 'inherit', 'closed', 'closed', '', '824-revision-v1', '', '', '2025-07-03 16:27:25', '2025-07-03 16:27:25', '', 824, 'http://localhost/final%20project_3/?p=845', 0, 'revision', '', 0),
