(1085, 1, '2025-07-08 03:55:46', '2025-07-08 03:55:46', '\n\n/* جعل الفوتر بعرض 100% */\nfooter,\n.site-footer,\n#colophon {\n    width: 100% !important;\n    max-width: 100% !important;\n    margin: 0 auto !important;\n    padding: 0 !important;\n}\n\n/* تأكيد على صفحات الكتجري في ووكومرس */\nbody.woocommerce.archive footer,\nbody.woocommerce.archive .site-footer,\nbody.woocommerce.archive #colophon {\n    width: 100% !important;\n    max-width: 100% !important;\n}\n\n.page-id-393 .wpforms-form button[type=submit] {\n    background-color: #000 !important;\n    border-color: #000 !important;\n    color: #fff !important;\n}\n \n.page-id-393 .wpforms-form button[type=submit]:hover {\n    background-color: #000 !important;\n}\n.page-id-393 .wpforms-form input,\n.page-id-393 .wpforms-form textarea {\n	border-color: #000 !important;\n}\n\ndiv.wpforms-container-full, div.wpforms-container-full .wpforms-form * {\n	position: relative;\n}\n\n.elementor-invisible {\n	opacity: 0;\n}\n.single-product .has-gallery-images .product-gallery-summary span.onsale {\n    left: px !important;\n}', 'botiga', '', 'inherit', 'closed', 'closed', '', '387-revision-v1', '', '', '2025-07-08 03:55:46', '2025-07-08 03:55:46', '', 387, 'http://localhost/final%20project_3/?p=1085', 0, 'revision', '', 0),
(1087, 1, '2025-07-08 04:09:15', '2025-07-08 04:09:15', '\n\n/* جعل الفوتر بعرض 100% */\nfooter,\n.site-footer,\n#colophon {\n    width: 100% !important;\n    max-width: 100% !important;\n    margin: 0 auto !important;\n    padding: 0 !important;\n}\n\n/* تأكيد على صفحات الكتجري في ووكومرس */\nbody.woocommerce.archive footer,\nbody.woocommerce.archive .site-footer,\nbody.woocommerce.archive #colophon {\n    width: 100% !important;\n    max-width: 100% !important;\n}\n:root {\n    --botiga_content_width: 1510px;\n}\n\n\n.page-id-393 .wpforms-form button[type=submit] {\n    background-color: #000 !important;\n    border-color: #000 !important;\n    color: #fff !important;\n}\n \n.page-id-393 .wpforms-form button[type=submit]:hover {\n    background-color: #000 !important;\n}\n.page-id-393 .wpforms-form input,\n.page-id-393 .wpforms-form textarea {\n	border-color: #000 !important;\n}\n\ndiv.wpforms-container-full, div.wpforms-container-full .wpforms-form * {\n	position: relative;\n}\n\n.elementor-invisible {\n	opacity: 0;\n}\n.single-product .has-gallery-images .product-gallery-summary span.onsale {\n    left: px !important;\n}', 'botiga', '', 'inherit', 'closed', 'closed', '', '387-revision-v1', '', '', '2025-07-08 04:09:15', '2025-07-08 04:09:15', '', 387, 'http://localhost/final%20project_3/?p=1087', 0, 'revision', '', 0),
