(27, 27, 'product_cat', 'Explore top mobile technology in two smart worlds', 0, 9),
(28, 28, 'product_cat', 'Affordable to flagship Android devices with great performance and variety.', 27, 6),
(29, 29, 'product_cat', 'Premium Apple smartphones with iOS, known for quality, security, and camera power.', 41, 3),
(30, 30, 'product_cat', 'Modern laptops for study, work, or gaming — from top brands worldwide.', 0, 15),
(31, 31, 'product_cat', 'Reliable laptops combining performance and value, perfect for everyday use.', 30, 3),
(32, 32, 'product_cat', 'Powerful business and student laptops known for durability and support.', 30, 3),
(33, 33, 'product_cat', 'Elegant and fast macOS laptops with top-tier design and battery life.', 30, 3),
(34, 34, 'product_cat', 'High-performance devices with gaming and productivity options.', 30, 3),
(35, 35, 'product_cat', 'Versatile and durable laptops for work, study, and business — trusted by professionals worldwide.', 30, 3),
(36, 36, 'product_cat', 'Stay connected and track your health with the latest Android and Apple smartwatches.', 0, 3),
(37, 37, 'product_cat', 'Experience rich, immersive sound with wireless and wired headphones from top brands.', 0, 3),
(38, 38, 'product_cat', 'Find essential tech accessories like fast chargers, cables, power banks, and more.', 0, 3),
(39, 39, 'product_cat', 'Explore our latest collection of Samsung smartphones, including Galaxy A, M, and S series. Known for their stunning displays, reliable performance, and cutting-edge features, Samsung phones offer something for everyone — from budget-friendly to premium flagships.\r\n\r\n', 28, 3),
(40, 40, 'product_cat', 'Shop Oppo’s top smartphones featuring elegant designs, high-resolution cameras, and fast-charging technology. Perfect for photography lovers and users who value sleek style with solid performance.\r\n', 28, 3),
(41, 41, 'product_cat', 'Experience the power of Apple with premium iPhones offering cutting-edge performance, elegant design, and long-term software support. From the latest models to trusted classics, find the perfect iOS device for your lifestyle.\r\n\r\n', 27, 3),
